/// <summary>
/// Lấy dữ liệu xuất từ lưới (kèm filter hiển thị) và filter bổ sung theo từng mẫu excel.
/// </summary>
private DataTable GetExportDataTable(string strExtraRowFilter)
{
    if (dtbData == null || dtbData.Rows.Count == 0)
        return null;

    DataTable dtbExport = dtbData.DefaultView.ToTable();
    string strFilter = gvData.RowFilter;
    if (!string.IsNullOrEmpty(strExtraRowFilter))
    {
        if (!string.IsNullOrEmpty(strFilter))
            strFilter = "(" + strFilter + ") AND (" + strExtraRowFilter + ")";
        else
            strFilter = strExtraRowFilter;
    }

    if (!string.IsNullOrEmpty(strFilter))
    {
        dtbExport.DefaultView.RowFilter = strFilter;
        dtbExport = dtbExport.DefaultView.ToTable();
    }

    return dtbExport;
}

private void AddExportOrderColumn(DataTable dtbExport)
{
    if (dtbExport == null)
        return;

    if (!dtbExport.Columns.Contains("Order"))
        dtbExport.Columns.Add("Order", typeof(int));

    for (int i = 0; i < dtbExport.Rows.Count; i++)
        dtbExport.Rows[i]["Order"] = i + 1;
}

private void FillExportHeaderValues(Hashtable hstValues)
{
    hstValues.Add("{Phòng ban}", lookupDepartmentID.Text);
    hstValues.Add("{Bộ phận}", lookupDepartmentID.Text);
    hstValues.Add("{Tháng}", dtmDate.Month.ToString());
    hstValues.Add("{Năm}", dtmDate.Year.ToString());
    hstValues.Add("{Tháng/Năm}", dtmDate.ToString("MM/yyyy"));
    hstValues.Add("{Ngày in}", DateTime.Now.ToString("dd/MM/yyyy"));
}

/// <summary>
/// Xuất excel bảng lương tháng theo mẫu (1: NV chính thức, 2: bảo vệ/HĐ ngắn, 3: bảng kê chuyển khoản).
/// </summary>
private void ExportExcelMonthSalary(int intMau)
{
    if (dtbData == null || dtbData.Rows.Count == 0)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    string strExtraFilter = "";
    string strTemplateFile = "";
    string strSavePrefix = "";
    string strAnchorColumn = "EmployeeCode";
    string[] arrCols = null;

    if (intMau == 1)
    {
        strExtraFilter = "ContractTypeID = 1";
        strTemplateFile = "Mau1_Luong_NhanVien.xlsx";
        strSavePrefix = "Mau1_Luong_NhanVien";
        arrCols = new string[] {
            "Order", "EmployeeCode", "Fullname", "DepartmentName", "PositionName", "SpecialJob",
            "SalaryQuotaCode", "SalaryQuotaName", "SalaryLevel", "SalaryRatio",
            "PositionSub", "TeacherSub", "OverFrameSub", "SpecialSub", "DepartmentSub", "DepartmentSubMoney",
            "TaskSub", "ToxicSub", "OtherSub", "UnitSalary",
            "InsuSalary", "TotalSalary", "InsuMoney", "DeductedSalary",
            "DeltaMoney", "DeltaDeducted", "NetSalary", "UnionFee", "AdvanceOffset", "TaskFee", "RealSalary"
        };
    }
    else if (intMau == 2)
    {
        strExtraFilter = "ContractTypeID <> 1";
        strTemplateFile = "Mau2_Luong_BaoVe.xlsx";
        strSavePrefix = "Mau2_Luong_BaoVe";
        arrCols = new string[] {
            "Order", "EmployeeCode", "Fullname", "DepartmentName", "PositionName",
            "SalaryLevel", "SalaryRatio", "UnitSalary", "TotalSalary", "InsuMoney",
            "DeductedSalary", "DeltaMoney", "NetSalary", "RealSalary"
        };
    }
    else
    {
        strExtraFilter = "IsSelected = 1";
        strTemplateFile = "Mau3_BangKe_ChuyenKhoan.xlsx";
        strSavePrefix = "Mau3_BangKe_ChuyenKhoan";
        strAnchorColumn = "Fullname";
        arrCols = new string[] {
            "Order", "EmployeeCode", "Fullname", "BankAccount", "PersonID",
            "DepartmentName", "NetSalary", "RealSalary"
        };
    }

    DataTable dtbExport = GetExportDataTable(strExtraFilter);
    if (dtbExport == null || dtbExport.Rows.Count == 0)
    {
        if (intMau == 3)
            MessageManager.Warning("Bạn phải tick chọn dữ liệu để xuất bảng kê chuyển khoản!");
        else
            MessageManager.Warning("Không có dữ liệu phù hợp mẫu excel đang chọn!");
        return;
    }

    AddExportOrderColumn(dtbExport);

    string timeStamp = DateTime.Now.ToString("yyyyMMdd_HHmmss");
    string strFileName = Application.StartupPath + "/Template/HRS/" + strTemplateFile;
    string strFileNamSaveAs = Application.StartupPath + "/Export/" + timeStamp + "_" + strSavePrefix + ".xlsx";

    Hashtable hstColumns = new Hashtable();
    Hashtable hstValues = new Hashtable();
    FillExportHeaderValues(hstValues);

    foreach (string col in arrCols)
    {
        if (dtbExport.Columns.Contains(col))
            hstColumns.Add(col, col);
    }

    if (Libs.Excel.ExportTemplateExcel(dtbExport, strFileName, strAnchorColumn, hstColumns, hstValues, strFileNamSaveAs))
        System.Diagnostics.Process.Start(strFileNamSaveAs);
    else
        ErrorManager.Error("Xuất dữ liệu thất bại!");
}

