/// <summary>
/// Lọc, sort, STT / STT theo phòng ban — dùng chung in danh sách và xuất Excel.
/// </summary>
private DataTable PrepareMonthSalaryOutputData(int intMau)
{
    if (dtbData == null || dtbData.Rows.Count == 0)
        return null;

    string strExtraFilter = "";
    if (intMau == 1)
        strExtraFilter = "ContractTypeID = 1";
    else if (intMau == 2)
        strExtraFilter = "ContractTypeID <> 1";
    else
        strExtraFilter = "IsSelected = 1";

    string strFilter = gvData.RowFilter;
    if (!string.IsNullOrEmpty(strExtraFilter))
    {
        if (!string.IsNullOrEmpty(strFilter))
            strFilter = "(" + strFilter + ") AND (" + strExtraFilter + ")";
        else
            strFilter = strExtraFilter;
    }

    DataTable dtbOut = dtbData.DefaultView.ToTable();
    if (!string.IsNullOrEmpty(strFilter))
    {
        dtbOut.DefaultView.RowFilter = strFilter;
        dtbOut = dtbOut.DefaultView.ToTable();
    }

    if (intMau == 1 || intMau == 2)
    {
        string strSort = "";
        if (dtbOut.Columns.Contains("Department_OrderIndex"))
            strSort = strSort + "Department_OrderIndex ASC,";
        if (dtbOut.Columns.Contains("Position_OrderIndex"))
            strSort = strSort + "Position_OrderIndex ASC,";
        if (dtbOut.Columns.Contains("LastName"))
            strSort = strSort + "LastName ASC,";
        if (dtbOut.Columns.Contains("FirstName"))
            strSort = strSort + "FirstName ASC,";

        if (strSort.Length > 0)
        {
            strSort = strSort.TrimEnd(',');
            dtbOut.DefaultView.Sort = strSort;
            dtbOut = dtbOut.DefaultView.ToTable();
        }
    }

    if (!dtbOut.Columns.Contains("Order"))
        dtbOut.Columns.Add("Order", typeof(int));
    if (!dtbOut.Columns.Contains("DeptOrder"))
        dtbOut.Columns.Add("DeptOrder", typeof(int));

    int intOrder = 0;
    int intDeptOrder = 0;
    string strPrevDept = null;
    for (int i = 0; i < dtbOut.Rows.Count; i++)
    {
        intOrder++;
        dtbOut.Rows[i]["Order"] = intOrder;

        if (intMau == 1 || intMau == 2)
        {
            string strDept = "";
            if (dtbOut.Columns.Contains("DepartmentName") && dtbOut.Rows[i]["DepartmentName"] != DBNull.Value)
                strDept = Convert.ToString(dtbOut.Rows[i]["DepartmentName"]);

            if (strPrevDept == null || strDept != strPrevDept)
            {
                intDeptOrder = 1;
                strPrevDept = strDept;
            }
            else
                intDeptOrder++;

            dtbOut.Rows[i]["DeptOrder"] = intDeptOrder;
        }
        else
            dtbOut.Rows[i]["DeptOrder"] = DBNull.Value;
    }

    return dtbOut;
}

private void PrintMonthSalary(int intMau)
{
    DataTable dtbPrint = PrepareMonthSalaryOutputData(intMau);
    if (dtbPrint == null || dtbPrint.Rows.Count == 0)
    {
        if (intMau == 3)
            MessageManager.Warning("Bạn phải tick chọn dữ liệu để in!");
        else
            MessageManager.Warning("Không có dữ liệu phù hợp mẫu in đang chọn!");
        return;
    }

    string strReport = "";
    if (intMau == 1)
        strReport = "Report/Salary/BangLuong_Mau1_LuongNhanVien.repx";
    else if (intMau == 2)
        strReport = "Report/Salary/BangLuong_Mau2_LuongBaoVe.repx";
    else
        strReport = "Report/Salary/BangLuong_Mau3_BangKeChuyenKhoan.repx";

    SystemManager.Report.frmReportView frm = new SystemManager.Report.frmReportView(dtbPrint, strReport, false);
    frm.SetParameter("pDepartment", lookupDepartmentID.Text);
    frm.SetParameter("pMonth", dtmDate);
    frm.SetParameter("par_THANG", dtmDate.Month);
    frm.SetParameter("par_NAM", dtmDate.Year);
    frm.SetParameter("par_NOW", DateTime.Now.ToString("dd/MM/yyyy"));
    frm.Show();
}

/// <summary>
/// Xuất excel bảng lương tháng (1: NV chính thức, 2: bảo vệ/HĐ ngắn, 3: bảng kê chuyển khoản).
/// </summary>
private void ExportExcelMonthSalary(int intMau)
{
    DataTable dtbExport = PrepareMonthSalaryOutputData(intMau);
    if (dtbExport == null || dtbExport.Rows.Count == 0)
    {
        if (intMau == 3)
            MessageManager.Warning("Bạn phải tick chọn dữ liệu để xuất bảng kê chuyển khoản!");
        else if (dtbData == null || dtbData.Rows.Count == 0)
            MessageManager.Warning("Không có dữ liệu để xuất!");
        else
            MessageManager.Warning("Không có dữ liệu phù hợp mẫu excel đang chọn!");
        return;
    }

    string strTemplateFile = "";
    string strSavePrefix = "";
    string strAnchorColumn = "Fullname";
    string[] arrCols = null;

    if (intMau == 1)
    {
        strTemplateFile = "Mau1_Luong_NhanVien.xlsx";
        strSavePrefix = "Mau1_Luong_NhanVien";
        arrCols = new string[] {
            "Order", "DeptOrder", "Fullname", "SpecialJob", "BankAccount", "SalaryRatio",
            "PositionSub", "OverFrameSub", "TaskSub", "ToxicSub", "TeacherSub", "SpecialSub", "DepartmentSub",
            "InsuSalary", "TotalSalary", "InsuMoney", "DeductedSalary", "DeltaMoney", "NetSalary", "Description"
        };
    }
    else if (intMau == 2)
    {
        strTemplateFile = "Mau2_Luong_BaoVe.xlsx";
        strSavePrefix = "Mau2_Luong_BaoVe";
        arrCols = new string[] {
            "Order", "DeptOrder", "Fullname", "DepartmentName", "PositionName",
            "SalaryLevel", "SalaryRatio", "UnitSalary", "TotalSalary", "InsuMoney",
            "DeductedSalary", "DeltaMoney", "NetSalary", "RealSalary"
        };
    }
    else
    {
        strTemplateFile = "Mau3_BangKe_ChuyenKhoan.xlsx";
        strSavePrefix = "Mau3_BangKe_ChuyenKhoan";
        arrCols = new string[] {
            "Order", "Fullname", "BankAccount", "PersonID", "DepartmentName", "NetSalary", "RealSalary"
        };
    }

    string timeStamp = DateTime.Now.ToString("yyyyMMdd_HHmmss");
    string strFileName = Application.StartupPath + "/MauExcel/HRS/" + strTemplateFile;
    string strFileNamSaveAs = Application.StartupPath + "/Export/" + timeStamp + "_" + strSavePrefix + ".xlsx";

    Hashtable hstColumns = new Hashtable();
    Hashtable hstValues = new Hashtable();
    hstValues.Add("{Phòng ban}", lookupDepartmentID.Text);
    hstValues.Add("{Bộ phận}", lookupDepartmentID.Text);
    hstValues.Add("{Tháng}", dtmDate.Month.ToString());
    hstValues.Add("{Năm}", dtmDate.Year.ToString());
    hstValues.Add("{Tháng/Năm}", dtmDate.ToString("MM/yyyy"));
    hstValues.Add("{Ngày in}", DateTime.Now.ToString("dd/MM/yyyy"));

    foreach (string col in arrCols)
    {
        if (dtbExport.Columns.Contains(col))
            hstColumns.Add(col, col);
    }

    if (Libs.Excel.ExportTemplateExcel(dtbExport, strFileName, strAnchorColumn, hstColumns, hstValues, strFileNamSaveAs))
        System.Diagnostics.Process.Start(strFileNamSaveAs);
    else
        ErrorManager.Error("Xuất dữ liệu thất bại!");
}

